WITH with_dims AS (SELECT s.*, o.channel FROM shipments s INNER JOIN orders o ON s.order_id = o.id WHERE o.store_id IN (22, 24)) SELECT DATE_TRUNC('MONTH', delivered_date) AS activity_month, STDDEV_SAMP(cost) AS cost_stddev, COUNT(*) AS cnt, SIZE(COLLECT_SET(carrier)) AS num_carriers, MAX(cost) FILTER (WHERE channel = 'web') AS web_max_cost, COUNT(*) AS row_count, GROUPING(DATE_TRUNC('MONTH', delivered_date)) AS grouping_level FROM with_dims GROUP BY ROLLUP (DATE_TRUNC('MONTH', delivered_date)) ORDER BY row_count DESC NULLS FIRST;
